func topKFrequent(nums []int, k int) []int {
    freq := map[int]int{}
    for _, v := range nums {
        freq[v]++
    }

    // 桶：下标是频率，值是该频率的元素
    buckets := make([][]int, len(nums)+1)
    for num, cnt := range freq {
        buckets[cnt] = append(buckets[cnt], num)
    }

    res := []int{}
    for i := len(buckets) - 1; i >= 0 && len(res) < k; i-- {
        res = append(res, buckets[i]...)
    }
    return res[:k]
}

func topKFrequent(nums []int, k int) []int {
    freq := map[int]int{}
    for _, v := range nums {
        freq[v]++
    }

    h := &FreqHeap{}
    heap.Init(h)
    for num, cnt := range freq {
        heap.Push(h, [2]int{num, cnt})
        if h.Len() > k {
            heap.Pop(h)
        }
    }

    res := make([]int, k)
    for i := k - 1; i >= 0; i-- {
        res[i] = heap.Pop(h).([2]int)[0]
    }
    return res
}

type FreqHeap [][2]int

func (h FreqHeap) Len() int           { return len(h) }
func (h FreqHeap) Less(i, j int) bool { return h[i][1] < h[j][1] }
func (h FreqHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *FreqHeap) Push(x any)        { *h = append(*h, x.([2]int)) }
func (h *FreqHeap) Pop() any {
    old := *h
    n := len(old)
    x := old[n-1]
    *h = old[:n-1]
    return x
}
